    out = [row[:] for row in grid]

    for c in range(w):
        # Bottom vertical marker: repeated cells, or a single bottom cell.
        if grid[h - 1][c] == 0:
            continue
        marker_color = grid[h - 1][c]
        r = h - 1
        while r >= 0 and grid[r][c] == marker_color:
            r -= 1
        if h - 1 - r < 1:
            continue

        # Rows where a horizontal bar has a one-cell gap at this column.
        bars = []
        for rr in range(h):
            if grid[rr][c] != 0 or c == 0 or c == w - 1:
                continue
            left, right = grid[rr][c - 1], grid[rr][c + 1]
            if left != 0 and left == right:
                bars.append((rr, left))

        if not bars:
            continue
        bars.sort()

        # Each bar colors the region above it, bounded by the previous bar.
        for i, (rr, color) in enumerate(bars):
            start = 0 if i == 0 else bars[i - 1][0] + 1
            for y in range(start, rr + 1):
                out[y][c] = color

        # The marker color fills the region below the lowest horizontal bar.
        for y in range(bars[-1][0] + 1, h):
            out[y][c] = marker_color

